import { getFullMedia } from "@/lib/api";
import MovieDetails from "@/components/MovieDetails";
import MusicDetails from "@/components/MusicDetails";

export default async function MediaPage({
  params,
}: {
  params: Promise<{ type: string; id: string }>;
}) {
  const { type, id } = await params; // ✅ MUST await
  const media = await getFullMedia(type, id);

  return (
    <div className="max-w-6xl mx-auto px-6 py-10 text-zinc-100">
      {/* HERO SECTION */}
      <div className="flex flex-col md:flex-row gap-10">
        <div
          className="absolute inset-0 -z-10 bg-cover bg-center blur-3xl opacity-20"
          style={{ backgroundImage: `url(${media.poster})` }}
        />

        <div className="flex-1">
          <h1 className="text-4xl font-semibold">{media.title}</h1>

          {media.subtitle && (
            <p className="text-zinc-400 mt-2">{media.subtitle}</p>
          )}

          <div className="flex flex-wrap gap-4 mt-4 text-sm text-zinc-400">
            {media.genre && <span>{media.genre}</span>}
            {media.release_date && <span>{media.release_date}</span>}
          </div>

          <div className="mt-6">
            <p>{media.description}</p>
          </div>

          {/* User Metadata */}
          <div className="mt-6 flex gap-3 flex-wrap">
            {media.tags?.map((tag: string) => (
              <span
                key={tag}
                className="px-3 py-1 bg-zinc-800 rounded-full text-xs"
              >
                #{tag}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* TYPE-SPECIFIC SECTIONS */}
      <div className="mt-12 space-y-10">
        {type === "movie" && <MovieDetails data={media.provider_data} />}
        {type === "music" && <MusicDetails data={media.provider_data} />}
      </div>
    </div>
  );
}
