import { Detail } from "./Detail";
import PreviewPlayer from "./PreviewPlayer";
import { Section } from "./Section";

export default function MusicDetails({ data }: any) {
  const duration =
    Math.floor(data.trackTimeMillis / 60000) +
    ":" +
    Math.floor((data.trackTimeMillis % 60000) / 1000)
      .toString()
      .padStart(2, "0");

  return (
    <div className="space-y-6">
      <Section title="Track Info">
        <Detail label="Artist" value={data.artistName} />
        <Detail label="Album" value={data.collectionName} />
        <Detail label="Track #" value={data.trackNumber} />
        <Detail label="Duration" value={duration} />
        <Detail label="Genre" value={data.primaryGenreName} />
      </Section>

      <Section title="Purchase Info">
        <Detail label="Track Price" value={`$${data.trackPrice}`} />
        <Detail label="Album Price" value={`$${data.collectionPrice}`} />
        <Detail label="Country" value={data.country} />
        <Detail label="Currency" value={data.currency} />
      </Section>

      {data.previewUrl && (
        <div>
          <h3 className="text-lg font-semibold mb-2">Preview</h3>
          import PreviewPlayer from "@/components/PreviewPlayer";
          {data.previewUrl && (
            <PreviewPlayer
              previewUrl={data.previewUrl}
              title={data.trackName}
              artist={data.artistName}
            />
          )}
        </div>
      )}
    </div>
  );
}
